insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'lote_3_v1'
from (values
('114.37.c.1.A',3,'An ASL IV class holds a signed debate on a school policy. This activity mainly builds:','["sustained signed exchange of ideas", "single-sign recall only", "written English grammar", "map skills"]'::jsonb,0,'Level IV exchanges are extended and detailed.','original'),
('114.37.c.1.A',4,'Which feature best marks a strong ASL IV exchange?','["avoiding eye contact", "smooth turn-taking with clear, detailed signing", "constant interruptions", "only yes and no signs"]'::jsonb,1,'Advanced exchanges show control of turn-taking and detail.','original'),
('114.37.c.1.B',3,'An ASL IV student follows a long signed story with several characters. This is an example of:','["reading a map", "solving a math puzzle", "comprehension of extended signed narrative", "spelling English words"]'::jsonb,2,'Intermediate-to-advanced learners follow extended signing.','original'),
('114.37.c.1.B',4,'Which signed task shows Level IV comprehension?','["copying a single sign", "reading subtitles only", "guessing at the topic", "carrying out multi-part instructions given only in ASL"]'::jsonb,3,'Extended instructions test comprehension.','original'),
('114.37.c.1.C',4,'A signer explains how a machine works using classifiers for each moving part. This shows skill in:','["conveying detailed information in ASL", "fingerspelling only", "silent reading", "spoken English"]'::jsonb,0,'Classifiers help describe objects and motion in detail.','original'),
('114.37.c.1.C',3,'Why do advanced signers combine concepts, phrases and sentences?','["to shorten every message to one sign", "to express connected ideas clearly", "to switch languages", "to avoid being understood"]'::jsonb,1,'Connected expression shows fluency.','original'),
('114.37.c.1.D',4,'A signer notices that changing the movement of a verb sign alters its meaning, such as repeated movement showing an ongoing action. This is a point of:','["syntax only", "spelling", "morphology", "phonology only"]'::jsonb,2,'Morphology covers how signs change form to change meaning.','original'),
('114.37.c.1.D',4,'Using a polite, formal register when signing with an unfamiliar adult demonstrates knowledge of:','["semantics", "phonology", "morphology", "pragmatics"]'::jsonb,3,'Pragmatics covers appropriate social use.','original'),
('114.37.c.1.E',3,'An ASL IV student creates a narrative that uses a repeated handshape to build rhythm. This follows:','["traditional features of ASL literature", "rules of chemistry", "rules of English meter", "rules of math"]'::jsonb,0,'Handshape repetition is a feature of ASL art forms.','original'),
('114.37.c.1.E',4,'Performing original signed literature for an audience involves:','["taking notes silently", "creating and expressing a work in ASL", "drawing a picture only", "reading aloud in English"]'::jsonb,1,'Performance expresses created literature.','original'),
('114.37.c.2.A',3,'In an ASL IV class, a student signs an explanation of why a flashing light can serve as a doorbell. This applies ASL to explain:','["chemical reactions", "algebra steps", "Deaf cultural norms and practices", "rules of baseball"]'::jsonb,2,'Visual alerts are part of Deaf cultural practice.','original'),
('114.37.c.2.A',4,'Which behavior reflects respect for Deaf cultural norms during a signed group conversation?','["looking at a phone", "speaking over the signer", "blocking sight lines", "making sure everyone can see the signer"]'::jsonb,3,'Visual access is a basic norm.','original'),
('114.37.c.2.B',3,'An ASL IV student signs a critique of a Deaf poet''s use of space. This shows:','["appreciation of ASL literature", "interest only in English poetry", "avoidance of the topic", "dislike of culture"]'::jsonb,0,'Critique shows deeper appreciation.','original'),
('114.37.c.2.B',4,'Why does appreciating ASL literature help a learner understand Deaf perspectives?','["it replaces conversation", "literature expresses values and experiences of the community", "it is unrelated to culture", "it is only entertainment"]'::jsonb,1,'Literature reflects cultural perspective.','original'),
('114.37.c.2.C',3,'A student signs a presentation on Deaf contributions in science and art. This shows:','["avoiding research", "a spelling quiz", "appreciation of contributions by the Deaf", "indifference"]'::jsonb,2,'Presentations apply ASL to cultural study.','original'),
('114.37.c.2.C',4,'Deaf individuals have shaped fields such as visual arts and education. Studying this reveals:','["nothing about culture", "limits of Deaf ability", "only historical trivia", "the range of Deaf achievement"]'::jsonb,3,'Contributions show achievement.','original'),
('114.37.c.2.D',3,'An ASL IV student explains in signing how a major event in Deaf education changed community life. This shows:','["in-depth understanding of Deaf history", "interest in unrelated topics", "no knowledge of history", "only memorized dates"]'::jsonb,0,'In-depth study explains causes and effects.','original'),
('114.37.c.2.D',4,'Studying Deaf history in depth helps a signer understand:','["only how to fingerspell", "why current community values developed", "nothing about culture", "only how to use a video phone"]'::jsonb,1,'History explains the present.','original'),
('114.37.c.3.A',3,'An ASL IV student uses scholarly articles and video archives to research Deaf culture. This is:','["skipping research", "relying on rumor", "using digital resources to gain extensive information", "copying text without credit"]'::jsonb,2,'Extensive research uses many reliable resources.','original'),
('114.37.c.3.A',4,'Which research practice is best for a project on ASL linguistics?','["avoiding sources", "trusting anonymous posts", "using only one blog", "comparing several credible sources"]'::jsonb,3,'Credible comparison improves accuracy.','original'),
('114.37.c.3.B',3,'Delivering a short lesson on photosynthesis in ASL shows ASL used to:','["expand knowledge of another subject", "stop practicing", "avoid science", "memorize vocabulary only"]'::jsonb,0,'Advanced signers can teach content through ASL.','original'),
('114.37.c.3.B',4,'At the intermediate-to-advanced level, which task best links ASL to history class?','["drawing a cartoon only", "signing a summary of a historical event", "reading silently", "skipping the assignment"]'::jsonb,1,'Content summaries use ASL.','original'),
('114.37.c.4.A',3,'An ASL IV student explains how ASL expresses time differently from English. This shows understanding of:','["tax rates", "ocean currents", "the nature of language", "musical notes"]'::jsonb,2,'Comparing grammar reveals language structure.','original'),
('114.37.c.4.A',4,'Which statement best reflects what comparing ASL and English teaches about language?','["grammar does not exist in ASL", "all languages are identical", "English is more complex than ASL", "different languages organize meaning in different ways"]'::jsonb,3,'Comparison shows structural variety.','original'),
('114.37.c.4.B',3,'A student compares how Deaf and hearing communities handle introductions. This shows understanding of:','["the nature of culture", "number theory", "plate tectonics", "cell division"]'::jsonb,0,'Cultural comparison reveals norms.','original'),
('114.37.c.4.B',4,'Which question best leads to a cultural comparison between Deaf culture and a student''s own?','["What metal is liquid?", "How do communities share news and celebrate together?", "How many sides does a hexagon have?", "What is the speed of sound?"]'::jsonb,1,'Comparison questions are about customs.','original'),
('114.37.c.4.C',3,'The way hearing people now use video relay shows how:','["language never changes", "video blocks communication", "Deaf culture and technology influence each other", "culture is unrelated to technology"]'::jsonb,2,'Technology and culture interact.','original'),
('114.37.c.4.C',4,'Borrowed signs and gestures moving between communities are evidence of:','["cultural isolation", "language disappearance", "no contact", "cross-cultural influence"]'::jsonb,3,'Influence travels both ways.','original'),
('114.37.c.5.A',3,'An ASL IV student volunteers as a signing guide at a community event. This shows:','["using ASL outside the classroom", "stopping practice", "taking a quiz", "avoiding use"]'::jsonb,0,'Community involvement builds skill.','original'),
('114.37.c.5.A',4,'At the intermediate-to-advanced level, a student can typically:','["only spell the alphabet", "discuss a wide range of topics with sustained signing", "only copy signs", "only share names"]'::jsonb,1,'Higher proficiency handles broader topics.','original'),
('114.37.c.5.B',3,'Which technology supports live signed conversation across long distances?','["voice-only phone", "radio", "video conferencing", "metronome"]'::jsonb,2,'Video allows signing across distance.','original'),
('114.37.c.5.B',4,'Why do Deaf signers often prefer video technology over audio-only tools?','["audio carries signs", "video is quieter", "audio is more visual", "video carries signs and facial grammar"]'::jsonb,3,'Signs and facial grammar are visual.','original'),
('114.37.c.5.C',3,'A lifelong learner at the intermediate-to-advanced level might:','["join a local Deaf club", "avoid signing events", "drop ASL", "skip practice"]'::jsonb,0,'Participation sustains learning.','original'),
('114.37.c.5.C',4,'Which action best shows long-term commitment to ASL?','["avoiding the Deaf community", "continuing to sign and learn after completing the course", "forgetting the signs", "practicing only before exams"]'::jsonb,1,'Lifelong learning is ongoing.','original'),
('114.38.c.1.A',4,'In an independent study, an advanced signer leads a sign-only seminar on a research topic. This builds:','["single-sign recall", "English spelling", "sustained, sophisticated ASL exchange", "map reading"]'::jsonb,2,'Advanced exchanges are extended and independent.','original'),
('114.38.c.1.A',4,'Which feature distinguishes advanced ASL exchanges from earlier levels?','["only simple greetings", "avoiding abstract topics", "only fingerspelling", "precision, flexibility and depth of expression"]'::jsonb,3,'Advanced levels handle abstract ideas.','original'),
('114.38.c.1.B',4,'An advanced signer fully understands a lengthy signed lecture. This shows:','["in-depth comprehension of ASL", "reliance on written notes only", "no comprehension", "partial guesswork"]'::jsonb,0,'In-depth comprehension covers complex signed material.','original'),
('114.38.c.1.B',4,'Which signed material is appropriate for in-depth comprehension at the advanced level?','["single signs", "complex stories and multi-step technical instructions", "simple greetings", "fingerspelled alphabets"]'::jsonb,1,'Advanced comprehension handles complex content.','original'),
('114.38.c.1.C',4,'An advanced signer describes a floor plan with classifiers and spatial grammar. This shows:','["reliance on speech", "limited vocabulary", "precise conveyance of information in ASL", "avoidance of detail"]'::jsonb,2,'Spatial grammar enables precise description.','original'),
('114.38.c.1.C',4,'Which choice best describes effective conveying of information at the advanced level?','["fragmented signs", "unfocused gestures", "speech-only messages", "clear, organized signing understood without assistance"]'::jsonb,3,'Clarity and organization define advanced signing.','original'),
('114.38.c.1.D',4,'An advanced student analyzes how handshape, location and movement combine to form a sign. This is study of:','["ASL phonology", "English spelling", "number theory", "musical notation"]'::jsonb,0,'Phonology covers the parts of signs.','original'),
('114.38.c.1.D',4,'Choosing signs whose meanings fit a context precisely shows control of:','["spelling", "semantics", "tempo", "cartography"]'::jsonb,1,'Semantics is about meaning.','original'),
('114.38.c.1.E',4,'An advanced signer creates an original ASL poem with deliberate handshape patterns. This follows:','["rules of a math proof", "a recipe", "traditional features of ASL literature", "rules of English rhyme only"]'::jsonb,2,'Original works honor tradition.','original'),
('114.38.c.1.E',4,'Expressing ASL literature at an advanced level includes:','["copying a printed English poem", "summarizing without signing", "watching videos only", "composing and performing complex signed works"]'::jsonb,3,'Performance requires composition and delivery.','original'),
('114.38.c.2.A',4,'An advanced student signs a detailed explanation of norms for getting attention, turn-taking and leave-taking. This shows:','["in-depth understanding of Deaf cultural norms", "no knowledge", "disinterest", "limited awareness"]'::jsonb,0,'Depth means thorough, accurate explanation.','original'),
('114.38.c.2.A',4,'Which statement shows a deep understanding of Deaf cultural norms?','["norms are the same as hearing norms", "norms reflect visual communication needs and shared values", "norms are unrelated to values", "norms are random habits"]'::jsonb,1,'Norms connect to values and visual needs.','original'),
('114.38.c.2.B',4,'An advanced signer produces a signed analysis of how a Deaf artist''s work reflects community identity. This shows:','["avoidance", "superficial reading", "in-depth appreciation of ASL literature", "indifference"]'::jsonb,2,'Deep appreciation includes analysis.','original'),
('114.38.c.2.B',4,'Why might an advanced student compare several Deaf storytellers?','["to avoid learning", "to ignore tradition", "to shorten the lesson", "to understand variety in style and perspective"]'::jsonb,3,'Comparison reveals style and perspective.','original'),
('114.38.c.2.C',4,'A signer presents a detailed study of Deaf contributors to arts and sciences. This demonstrates:','["in-depth appreciation of Deaf contributions", "avoidance of research", "unrelated trivia", "minimal interest"]'::jsonb,0,'Depth includes thorough research.','original'),
('114.38.c.2.C',4,'Which outcome shows in-depth appreciation of Deaf contributions?','["listing names only", "connecting individual achievements to community impact", "memorizing a single date", "avoiding discussion"]'::jsonb,1,'Connection shows depth.','original'),
('114.38.c.2.D',4,'An advanced student explains how historical policies shaped Deaf education and identity. This shows:','["indifference", "surface knowledge", "in-depth understanding of Deaf history", "avoidance of history"]'::jsonb,2,'Depth links policy, education and identity.','original'),
('114.38.c.2.D',4,'Why is a deep grasp of Deaf history relevant to today''s Deaf community?','["it concerns only the past", "it is optional trivia", "it has no connection", "it explains current issues and values"]'::jsonb,3,'History shapes the present.','original'),
('114.38.c.3.A',4,'An advanced signer gathers extensive information from journals, archives and community sources. This shows:','["using digital resources for extensive research", "copying without credit", "using one source only", "avoiding research"]'::jsonb,0,'Extensive research draws on many sources.','original'),
('114.38.c.3.A',4,'Which practice supports strong independent research on ASL?','["skipping citations", "evaluating the credibility of each source", "using rumors", "accepting every claim"]'::jsonb,1,'Credibility evaluation is basic research skill.','original'),
('114.38.c.3.B',4,'An advanced signer teaches a lesson in ASL on a complex topic from another subject. This shows ASL used to:','["memorize vocabulary only", "stop signing", "obtain, reinforce and expand knowledge in other subjects", "avoid the subject"]'::jsonb,2,'Advanced proficiency supports learning anywhere.','original'),
('114.38.c.3.B',4,'At the advanced proficiency level, which task best links ASL and economics?','["fingerspelling the alphabet", "copying notes silently", "skipping the lesson", "signing a clear explanation of supply and demand"]'::jsonb,3,'Complex content can be signed.','original'),
('114.38.c.4.A',4,'An advanced signer analyzes how ASL grammar encodes aspect and agreement through space and movement. This shows understanding of:','["the nature of language", "tax law", "ocean tides", "music theory"]'::jsonb,0,'Analysis of grammar reveals language structure.','original'),
('114.38.c.4.A',4,'What does advanced comparison of ASL and a spoken language demonstrate?','["ASL lacks structure", "languages differ in modality yet share complex structure", "spoken languages are the only real languages", "modality determines value"]'::jsonb,1,'Modality differs but structure is complex.','original'),
('114.38.c.4.B',4,'An advanced signer examines how values around communication differ between Deaf and hearing communities. This shows understanding of:','["plate tectonics", "number bases", "the nature of culture", "cell structure"]'::jsonb,2,'Values are part of culture.','original'),
('114.38.c.4.B',4,'Which topic offers an advanced cultural comparison between Deaf culture and another culture?','["boiling points", "a multiplication table", "the speed of light", "how communities pass stories and traditions across generations"]'::jsonb,3,'Traditions and storytelling are cultural.','original'),
('114.38.c.4.C',4,'An advanced signer traces how technology and policy have changed ASL use. This shows:','["how culture and language influence each other", "culture is fixed", "language never changes", "technology is irrelevant"]'::jsonb,0,'Language and culture change together.','original'),
('114.38.c.4.C',4,'Cross-influence between languages is most clearly shown by:','["isolated languages", "borrowing of signs and words between communities", "extinct languages", "unrelated alphabets"]'::jsonb,1,'Borrowing is evidence of influence.','original'),
('114.38.c.5.A',4,'An advanced signer leads a workshop for beginning students in the community. This shows:','["avoiding ASL", "ending practice", "applying ASL beyond the classroom", "taking a quiz"]'::jsonb,2,'Leading a workshop applies advanced skill.','original'),
('114.38.c.5.A',4,'At the advanced proficiency level, a student can typically:','["copy signs", "use only fingerspelling", "share only names", "discuss abstract and complex topics in ASL"]'::jsonb,3,'Advanced proficiency handles abstraction.','original'),
('114.38.c.5.B',4,'Which technology is essential for signers who live far apart?','["high-quality video communication", "text-free messages", "audio-only calls", "radio broadcasts"]'::jsonb,0,'Video supports signed conversation at distance.','original'),
('114.38.c.5.B',4,'A team of signers collaborates on a project using shared video. This shows technology used to:','["hide information", "communicate with the Deaf/ASL community", "avoid communication", "replace signing with speech"]'::jsonb,1,'Video collaboration supports the community.','original'),
('114.38.c.5.C',4,'A lifelong ASL learner at the advanced level might:','["hide from the community", "stop after graduation", "mentor others and keep learning new regional signs", "avoid new vocabulary"]'::jsonb,2,'Lifelong learners keep growing.','original'),
('114.38.c.5.C',4,'Which habit best signals a commitment to lifelong ASL learning?','["never signing again", "ignoring feedback", "practicing only for tests", "seeking out signing opportunities for enrichment"]'::jsonb,3,'Enrichment drives lifelong learning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Languages Other Than English' and d.language = 'en'
on conflict (fingerprint) do nothing;
